function hashId(value) {
  let h = 2166136261;
  value = String(value || '');
  for (let i = 0; i < value.length; i++) {
    h ^= value.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return (h >>> 0).toString(16).padStart(8, '0');
}

function findNumeric(root, names) {
  const wanted = new Set(names.map(x => String(x).toLowerCase()));
  const seen = new Set();
  function walk(value) {
    if (!value || typeof value !== 'object' || seen.has(value)) return null;
    seen.add(value);
    if (!Array.isArray(value)) {
      for (const [k, v] of Object.entries(value)) {
        if (wanted.has(String(k).toLowerCase())) {
          const n = Number(v);
          if (Number.isFinite(n)) return n;
        }
      }
    }
    for (const v of Object.values(value)) {
      if (v && typeof v === 'object') {
        const got = walk(v);
        if (got !== null) return got;
      }
    }
    return null;
  }
  return walk(root);
}

const thresholdRaw = $('Fetch NOAA Flood Thresholds').first().json || {};
const waterRaw = $('Fetch NOAA Water Level').first().json || {};
const nwsRaw = $('Fetch NWS Active Alerts').first().json || {};
const ctx = $('Load Flood Watch Context').first().json || {};
const watched = Array.isArray(ctx.watched) ? ctx.watched : [];
const previousCategory = String(ctx.previous_category || 'NONE').toUpperCase();

const thresholds = {
  action: findNumeric(thresholdRaw, ['action']),
  nos_minor: findNumeric(thresholdRaw, ['nos_minor', 'nosMinor']),
  nos_moderate: findNumeric(thresholdRaw, ['nos_moderate', 'nosModerate']),
  nos_major: findNumeric(thresholdRaw, ['nos_major', 'nosMajor']),
  nws_minor: findNumeric(thresholdRaw, ['nws_minor', 'nwsMinor']),
  nws_moderate: findNumeric(thresholdRaw, ['nws_moderate', 'nwsModerate']),
  nws_major: findNumeric(thresholdRaw, ['nws_major', 'nwsMajor'])
};

const waterRows = Array.isArray(waterRaw.data) ? waterRaw.data : [];
if (!waterRows.length) throw new Error('NOAA water-level response had no data rows.');
const latest = waterRows[waterRows.length - 1] || {};
const level = Number(latest.v);
if (!Number.isFinite(level)) throw new Error('NOAA latest water level was not numeric.');
if (!Number.isFinite(thresholds.nos_minor) && !Number.isFinite(thresholds.nws_minor)) {
  throw new Error('NOAA flood threshold response did not contain a usable minor threshold.');
}

const observedAt = latest.t ? new Date(String(latest.t).replace(' ', 'T') + (String(latest.t).includes('Z') ? '' : ':00Z')).toISOString() : new Date().toISOString();
const minor = Number.isFinite(thresholds.nos_minor) ? thresholds.nos_minor : thresholds.nws_minor;
const moderate = Number.isFinite(thresholds.nos_moderate) ? thresholds.nos_moderate : thresholds.nws_moderate;
const major = Number.isFinite(thresholds.nos_major) ? thresholds.nos_major : thresholds.nws_major;
let category = 'NONE';
if (Number.isFinite(major) && level >= major) category = 'MAJOR';
else if (Number.isFinite(moderate) && level >= moderate) category = 'MODERATE';
else if (Number.isFinite(minor) && level >= minor) category = 'MINOR';
else if (Number.isFinite(thresholds.action) && level >= thresholds.action) category = 'ACTION';

const rank = {NONE:0, ACTION:1, MINOR:2, MODERATE:3, MAJOR:4};
const priorityFor = c => ({NONE:2, ACTION:2, MINOR:3, MODERATE:4, MAJOR:5}[c] || 3);
const watchedList = watched.slice(0, 12).map(w => {
  const name = String(w.display_name || w.watch_id || 'Watched location');
  const address = String(w.address || '').trim();
  return address ? `${name} (${address})` : name;
});
const watchedText = watched.length ? ` Watched FEMA-zone locations: ${watchedList.join('; ')}${watched.length > watchedList.length ? `; +${watched.length - watchedList.length} more` : ''}.` : '';
const alerts = [];

if (category !== previousCategory) {
  const thresholdText = [
    Number.isFinite(minor) ? `Minor ${minor.toFixed(2)} ft` : null,
    Number.isFinite(moderate) ? `Moderate ${moderate.toFixed(2)} ft` : null,
    Number.isFinite(major) ? `Major ${major.toFixed(2)} ft` : null
  ].filter(Boolean).join(', ');
  const recovery = category === 'NONE' && previousCategory !== 'NONE';
  const direction = (rank[category] || 0) > (rank[previousCategory] || 0) ? 'up' : 'down';
  const title = recovery
    ? 'Hudson River water level back below flood threshold'
    : `Hudson River water level: ${category} flood category`;
  const message = `NOAA station 8518750 The Battery observed ${level.toFixed(2)} ft relative to MHHW at ${observedAt}. Previous category: ${previousCategory}; current category: ${category}. Official NOAA/NWS station thresholds used dynamically${thresholdText ? `: ${thresholdText}` : ''}.${watchedText}`;
  const sourceEventId = `${observedAt}|${previousCategory}|${category}`;
  alerts.push({
    schema_version: '1.0',
    alert_id: `NOAA_TIDE:${hashId(sourceEventId)}`,
    source: 'NOAA_TIDE',
    source_event_id: sourceEventId,
    category: 'OEM',
    subtype: recovery ? 'FLOOD_RECOVERY' : 'WATER_LEVEL_THRESHOLD',
    status: recovery ? 'RESOLVED' : 'ACTIVE',
    event_action: recovery ? 'UPDATE' : 'NEW',
    title,
    message,
    priority: priorityFor(category),
    county: 'Hudson',
    municipality: 'Weehawken',
    location: {label:'Weehawken Waterfront / Hudson River',address:'',state:'NJ',zip:'',latitude:40.7690,longitude:-74.0200,block:'',lot:'',qualifier:'',parcel_id:''},
    tags: ['flood','coastal','water_level','hudson_river',category.toLowerCase()],
    click_url: 'https://tidesandcurrents.noaa.gov/stationhome.html?id=8518750',
    source_url: 'https://api.tidesandcurrents.noaa.gov/api/prod/datagetter',
    observed_at: observedAt,
    source_updated_at: observedAt,
    received_at: new Date().toISOString(),
    expires_at: null,
    metadata: {station_id:'8518750',station_name:'The Battery, NY',water_level_mhhw_ft:level,previous_category:previousCategory,current_category:category,direction,thresholds,watched_count:watched.length,watched}
  });
}

const relevantEvents = new Set([
  'Coastal Flood Advisory','Coastal Flood Warning','Coastal Flood Watch','Coastal Flood Statement',
  'Flood Advisory','Flood Warning','Flood Watch','Flash Flood Warning','Flash Flood Statement',
  'Storm Surge Warning','Storm Surge Watch'
]);
const nwsFeatures = Array.isArray(nwsRaw.features) ? nwsRaw.features : [];
for (const feature of nwsFeatures) {
  const p = feature.properties || {};
  const event = String(p.event || '').trim();
  if (!relevantEvents.has(event)) continue;
  const officialId = String(feature.id || p.id || `${event}|${p.sent || p.effective || ''}|${p.areaDesc || ''}`);
  let priority = 3;
  if (/Warning|Flash Flood/i.test(event)) priority = 5;
  else if (/Watch/i.test(event)) priority = 4;
  else if (/Advisory/i.test(event)) priority = 3;
  else priority = 2;
  const headline = String(p.headline || '').trim();
  const description = String(p.description || '').trim();
  const instruction = String(p.instruction || '').trim();
  const area = String(p.areaDesc || '').trim();
  const pieces = [headline, description, instruction].filter(Boolean);
  let message = pieces.join('\n\n');
  if (area) message += `${message ? '\n\n' : ''}Affected area: ${area}.`;
  message += watchedText;
  alerts.push({
    schema_version: '1.0',
    alert_id: `NWS_FLOOD:${hashId(officialId)}`,
    source: 'NWS_FLOOD',
    source_event_id: officialId,
    category: 'OEM',
    subtype: event.toUpperCase().replace(/[^A-Z0-9]+/g,'_'),
    status: 'ACTIVE',
    event_action: 'NEW',
    title: headline || event,
    message: message.slice(0, 12000),
    priority,
    county: 'Hudson',
    municipality: 'Weehawken',
    location: {label:'Weehawken, NJ',address:'',state:'NJ',zip:'',latitude:40.7690,longitude:-74.0200,block:'',lot:'',qualifier:'',parcel_id:''},
    tags: ['flood','nws','weather',event.toLowerCase().replace(/[^a-z0-9]+/g,'_')],
    click_url: String(p.web || p['@id'] || feature.id || 'https://www.weather.gov/'),
    source_url: 'https://api.weather.gov/alerts/active?point=40.7690,-74.0200',
    observed_at: p.sent || p.effective || new Date().toISOString(),
    source_updated_at: p.sent || null,
    received_at: new Date().toISOString(),
    expires_at: p.expires || p.ends || null,
    metadata: {event,severity:p.severity||null,certainty:p.certainty||null,urgency:p.urgency||null,area_desc:area,watched_count:watched.length,watched}
  });
}

for (const alert of alerts) {
  alert.search_text = [alert.source,alert.category,alert.subtype,alert.title,alert.message,...alert.tags].filter(Boolean).join(' ');
}

return [{json:{
  observation:{source:'NOAA_TIDE',station_id:'8518750',observed_at:observedAt,water_level_mhhw_ft:level,predicted_level_mhhw_ft:null,flood_category:category,title:'The Battery, NY',payload:{quality:latest.q||null,flags:latest.f||null,sigma:latest.s||null,thresholds,previous_category:previousCategory,watched_count:watched.length}},
  thresholds,
  watched_count: watched.length,
  nws_active_count: nwsFeatures.filter(f => relevantEvents.has(String((f.properties||{}).event||'').trim())).length,
  alerts
}}];
